using BenchmarkDotNet.Attributes;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using OptimizingEfCoreQueries.Shared;
using OptimizingEfCoreQueries.Solutions;

namespace OptimizingEfCoreQueries.Benchmarks;

// Baseline deactivates orders row-by-row via SaveChanges; Optimized calls the
// agent-owned BulkUpdateSolution.Run. The operation mutates data, so it uses
// MutationBenchmarkConfig (one invocation per iteration) and [IterationSetup]
// restores every order to active before each measured run. Do not edit this file
// — edit Solutions/BulkUpdate.cs.
[Config(typeof(MutationBenchmarkConfig))]
public class BulkUpdateBenchmark
{
    // Orders are seeded one-per-minute from 2020-01-01, so this cutoff makes
    // roughly the first half of them stale.
    private static readonly DateTime Cutoff = new(2020, 1, 8);
    private SqliteConnection _connection = null!;

    [GlobalSetup]
    public void Setup()
    {
        _connection = AppDbContext.OpenSharedConnection();
        using (var db = AppDbContext.Create(_connection))
        {
            db.Database.EnsureCreated();
            SeedData.SeedOrders(db, orders: 20000);
        }

        // Confirm both approaches deactivate exactly the same rows.
        Reset();
        Baseline();
        var baselineIds = InactiveIds();
        Reset();
        Optimized();
        var optimizedIds = InactiveIds();
        EquivalenceGuard.SameResults(baselineIds, optimizedIds, id => id);
        Reset();
    }

    [IterationSetup]
    public void ResetBeforeIteration() => Reset();

    [GlobalCleanup]
    public void Cleanup() => _connection.Dispose();

    [Benchmark(Baseline = true)]
    public int Baseline()
    {
        using var db = AppDbContext.Create(_connection);
        var stale = db.Orders.Where(o => o.CreatedAt < Cutoff).ToList();
        foreach (var order in stale)
        {
            order.IsActive = false;
        }

        db.SaveChanges();
        return stale.Count;
    }

    [Benchmark]
    public int Optimized()
    {
        using var db = AppDbContext.Create(_connection);
        return BulkUpdateSolution.Run(db, Cutoff);
    }

    private void Reset()
    {
        using var db = AppDbContext.Create(_connection);
        db.Orders.ExecuteUpdate(s => s.SetProperty(o => o.IsActive, true));
    }

    private List<string> InactiveIds()
    {
        using var db = AppDbContext.Create(_connection);
        return db.Orders
            .Where(o => !o.IsActive)
            .OrderBy(o => o.Id)
            .Select(o => o.Id.ToString())
            .ToList();
    }
}
